import React, { useEffect, useRef } from 'react'
import gsap from 'gsap'
import BlurText from '../components/BlurText'

function Hero() {
    const typingRef = useRef(null)
    const heroContentRef = useRef(null)
    const codeCardRef = useRef(null)

    useEffect(() => {
        // Staggered animation for hero content elements
        if (heroContentRef.current) {
            gsap.fromTo(
                heroContentRef.current.querySelectorAll('[data-hero-animate]'),
                { opacity: 0, y: 30 },
                {
                    opacity: 1,
                    y: 0,
                    duration: 0.8,
                    stagger: 0.15,
                    ease: 'power3.out',
                }
            )
        }

        // Code card animation
        if (codeCardRef.current) {
            gsap.fromTo(
                codeCardRef.current,
                { opacity: 0, x: 50, rotateY: 10 },
                {
                    opacity: 1,
                    x: 0,
                    rotateY: 0,
                    duration: 1,
                    delay: 0.3,
                    ease: 'power3.out',
                }
            )
        }
    }, [])

    useEffect(() => {
        const typingText = typingRef.current
        if (!typingText) return

        const words = [
            'Web Experiences.',
            'Front-End Developer.',
            'Software Engineer.',
            'UI/UX Enthusiast.',
            'Creative Coder.'
        ]

        let wordIndex = 0
        let charIndex = 0
        let isDeleting = false
        let speed = 100
        let timeoutId = null

        const typeEffect = () => {
            const currentWord = words[wordIndex]

            if (isDeleting) {
                if (charIndex > 0) {
                    charIndex -= 1
                    typingText.textContent = currentWord.substring(0, charIndex)
                }
                speed = 70
            } else {
                if (charIndex < currentWord.length) {
                    charIndex += 1
                    typingText.textContent = currentWord.substring(0, charIndex)
                }
                speed = 130
            }

            if (!isDeleting && charIndex === currentWord.length) {
                speed = 1500
                isDeleting = true
            }

            if (isDeleting && charIndex === 0) {
                isDeleting = false
                wordIndex = (wordIndex + 1) % words.length
                speed = 300
            }

            timeoutId = setTimeout(typeEffect, speed)
        }

        timeoutId = setTimeout(typeEffect, speed)

        return () => {
            if (timeoutId) clearTimeout(timeoutId)
        }
    }, [])

    return (
        <div>
            <section className="hero" id="home">
                <div className="hero-container">
                    <div className="hero-content" ref={heroContentRef}>
                        <div className="hero-badge" data-hero-animate>
                            <span />
                            Available for freelance
                        </div>
                        <p className="hero-subtitle" data-hero-animate>FRONT-END DEVELOPER</p>
                        <h1 data-hero-animate style={{ lineHeight: '1.2' }}>
                            <BlurText
                                text="Hi, I'm Adel"
                                delay={0}
                                duration={1.5}
                                animateBy="words"
                                direction="top"
                            />
                            <br />
                            <BlurText
                                text="I Build Modern"
                                delay={0.8}
                                duration={1.5}
                                animateBy="words"
                                direction="top"
                            />
                            <br />
                            <span className="typing-wrapper">
                                <span className="typing-text" ref={typingRef} id="typingText" />
                                <span className="typing-cursor">|</span>
                            </span>
                        </h1>
                        <p className="hero-description" data-hero-animate>
                            I turn ideas and designs into modern, responsive and interactive
                            websites using clean and scalable code.
                        </p>
                        <div className="hero-buttons" data-hero-animate>
                            <a href="#projects" className="hero-btn primary-btn">
                                View My Projects <i className="fa-solid fa-arrow-right" />
                            </a>
                            <a href="#contact" className="hero-btn secondary-btn">
                                Let's Talk
                            </a>
                        </div>
                        <div className="hero-tech" data-hero-animate>
                            <span>HTML</span>
                            <span>CSS</span>
                            <span>JavaScript</span>
                            <span>React</span>
                        </div>
                    </div>
                    <div className="hero-visual">
                        <div className="code-card" ref={codeCardRef}>
                            <div className="code-header">
                                <div className="window-dots">
                                    <span />
                                    <span />
                                    <span />
                                </div>
                                <p>developer.js</p>
                            </div>
                            <div className="code-body">
                                <p>
                                    <span className="code-purple">const</span>{" "}
                                    <span className="code-blue">developer</span> ={" "}
                                    <span className="code-yellow">{"{"}</span>
                                </p>
                                <p className="indent">
                                    <span className="code-red">name:</span>{" "}
                                    <span className="code-green">"Adel Mohamed"</span>,
                                </p>
                                <p className="indent">
                                    <span className="code-red">role:</span>{" "}
                                    <span className="code-green">"Front-End Developer"</span>,
                                </p>
                                <p className="indent">
                                    <span className="code-red">skills:</span>{" "}
                                    <span className="code-yellow">[</span>
                                </p>
                                <p className="indent-2">
                                    <span className="code-green">"HTML"</span>,
                                </p>
                                <p className="indent-2">
                                    <span className="code-green">"CSS"</span>,
                                </p>
                                <p className="indent-2">
                                    <span className="code-green">"JavaScript"</span>,
                                </p>
                                <p className="indent-2">
                                    <span className="code-green">"React"</span>
                                </p>
                                <p className="indent">
                                    <span className="code-yellow">]</span>
                                </p>
                                <p>
                                    <span className="code-yellow">{"}"}</span>;
                                </p>
                                <div className="code-cursor" />
                            </div>
                        </div>
                    </div>
                </div>
            </section>
        </div>
    )
}

export default Hero