import React, { useEffect, useState } from 'react'

const navItems = [
    { label: 'Home', href: '#home' },
    { label: 'About', href: '#about' },
    { label: 'Skills', href: '#skills' },
    { label: 'Projects', href: '#projects' },
    { label: 'Contact', href: '#contact' }
]

function Navbar() {
    const [menuOpen, setMenuOpen] = useState(false)
    const [activeLink, setActiveLink] = useState('#home')

    useEffect(() => {
        const syncActiveLink = () => {
            const sections = document.querySelectorAll('section[id]')
            let current = '#home'

            sections.forEach((section) => {
                const sectionTop = section.offsetTop - 120
                if (window.scrollY >= sectionTop) {
                    current = `#${section.getAttribute('id')}`
                }
            })

            setActiveLink(current)
        }

        syncActiveLink()
        window.addEventListener('scroll', syncActiveLink)

        return () => window.removeEventListener('scroll', syncActiveLink)
    }, [])

    useEffect(() => {
        const hamburger = document.getElementById('hamburger')
        const navLinks = document.getElementById('navLinks')

        if (!hamburger || !navLinks) return

        const toggleMenu = () => {
            setMenuOpen((prev) => !prev)
        }

        const closeMenu = () => setMenuOpen(false)

        hamburger.addEventListener('click', toggleMenu)
        navLinks.querySelectorAll('a').forEach((link) => {
            link.addEventListener('click', () => {
                setActiveLink(link.getAttribute('href'))
                closeMenu()
            })
        })

        return () => {
            hamburger.removeEventListener('click', toggleMenu)
            navLinks.querySelectorAll('a').forEach((link) => {
                link.removeEventListener('click', () => {
                    setActiveLink(link.getAttribute('href'))
                    closeMenu()
                })
            })
        }
    }, [])

    return (
        <div>
            <nav className="navbar">
                <div className="nav-container">
                    <a href="#home" className="logo">
                        <span className="logo-icon">
                            {" "}
                            <img src="/assets/img/photo_2026-08-07_00-50-58.jpg" alt="" />{" "}
                        </span>
                        <span className="logo-name">Adel Mohamed</span>
                    </a>
                    <ul className={menuOpen ? 'nav-links open' : 'nav-links'} id="navLinks">
                        {navItems.map((item) => (
                            <li key={item.href}>
                                <a
                                    href={item.href}
                                    className={activeLink === item.href ? 'active' : ''}
                                >
                                    {item.label}
                                </a>
                            </li>
                        ))}
                    </ul>
                    <a href="#contact" className="nav-btn">
                        Let's Talk
                        <i className="fa-solid fa-arrow-up-right-from-square" />
                    </a>
                    <button
                        className={menuOpen ? 'hamburger active' : 'hamburger'}
                        id="hamburger"
                        aria-label="Toggle navigation"
                        aria-expanded={menuOpen}
                    >
                        <span />
                        <span />
                        <span />
                    </button>
                </div>
            </nav>
        </div>
    )
}

export default Navbar