import React from 'react'

function Journey() {
    return (
        <div>
            <section className="journey" id="journey">
                <div className="journey-container">
                    <div className="section-heading journey-heading">
                        <div className="section-label new-label-sec">MY JOURNEY</div>
                        <h2>
                            LEARNING. <span>BUILDING. GROWING.</span>
                        </h2>
                        <p>
                            A journey of continuous learning, practical training, and building
                            real-world web projects.
                        </p>
                    </div>
                    <div className="timeline">
                        <div className="timeline-item">
                            <div className="timeline-dot">01</div>
                            <div className="timeline-card">
                                <div className="timeline-card-top">
                                    <span className="timeline-type">EDUCATION</span>
                                    <span className="timeline-date">2024 — PRESENT</span>
                                </div>
                                <div className="timeline-icon">
                                    <i className="fa-solid fa-graduation-cap" />
                                </div>
                                <h3>Bachelor of Computer &amp; Information Science</h3>
                                <h4>Mansoura University</h4>
                                <p>
                                    Studying computer and information science while developing a strong
                                    foundation in programming, web development and computer science
                                    concepts.
                                </p>
                            </div>
                        </div>
                        <div className="timeline-item timeline-right">
                            <div className="timeline-dot">02</div>
                            <div className="timeline-card">
                                <div className="timeline-card-top">
                                    <span className="timeline-type">TRAINING</span>
                                    <span className="timeline-date">FRONT-END</span>
                                </div>
                                <div className="timeline-icon green-timeline-icon">
                                    <i className="fa-solid fa-laptop-code" />
                                </div>
                                <h3>Web Design</h3>
                                <h4>
                                    National Telecommunication Institute Web Design Training (NTI)
                                </h4>
                                <p>
                                    Hands-on experience with HTML, CSS, JavaScript, Bootstrap, focusing
                                    on responsive and interactive web interfaces.
                                </p>
                            </div>
                        </div>
                        <div className="timeline-item">
                            <div className="timeline-dot">03</div>
                            <div className="timeline-card">
                                <div className="timeline-card-top">
                                    <span className="timeline-type">PRACTICE</span>
                                    <span className="timeline-date">ONGOING</span>
                                </div>
                                <div className="timeline-icon">
                                    <i className="fa-solid fa-rocket" />
                                </div>
                                <h3>Building Real Projects</h3>
                                <h4>Front-End Projects &amp; Experiments</h4>
                                <p>
                                    Turning what I learn into practical projects, experimenting with UI,
                                    animations, responsive layouts and modern front-end development.
                                </p>
                            </div>
                        </div>
                    </div>
                </div>
            </section>

        </div>
    )
}

export default Journey