import React, { useRef, useEffect } from 'react'
import gsap from 'gsap'
import { ScrollTrigger } from 'gsap/ScrollTrigger'
import BlurText from './components/BlurText'

gsap.registerPlugin(ScrollTrigger)

function About() {
    const aboutHeadingRef = useRef(null)
    const aboutCardsRef = useRef(null)
    const flipCardRef = useRef(null)

    useEffect(() => {
        // Scroll reveal for heading
        if (aboutHeadingRef.current) {
            gsap.fromTo(
                aboutHeadingRef.current,
                { opacity: 0, y: 50 },
                {
                    opacity: 1,
                    y: 0,
                    duration: 0.8,
                    ease: 'power3.out',
                    scrollTrigger: {
                        trigger: aboutHeadingRef.current,
                        start: 'top 80%',
                        toggleActions: 'play none none none',
                    },
                }
            )
        }

        // Staggered animation for cards
        if (aboutCardsRef.current) {
            gsap.fromTo(
                aboutCardsRef.current.querySelectorAll('[data-about-card]'),
                { opacity: 0, y: 40 },
                {
                    opacity: 1,
                    y: 0,
                    duration: 0.6,
                    stagger: 0.1,
                    ease: 'power3.out',
                    scrollTrigger: {
                        trigger: aboutCardsRef.current,
                        start: 'top 75%',
                        toggleActions: 'play none none none',
                    },
                }
            )
        }

        // Flip card entrance
        if (flipCardRef.current) {
            gsap.fromTo(
                flipCardRef.current,
                { opacity: 0, x: 40, rotateY: 15 },
                {
                    opacity: 1,
                    x: 0,
                    rotateY: 0,
                    duration: 0.8,
                    ease: 'power3.out',
                    scrollTrigger: {
                        trigger: flipCardRef.current,
                        start: 'top 75%',
                        toggleActions: 'play none none none',
                    },
                }
            )
        }

        return () => {
            ScrollTrigger.getAll().forEach((trigger) => trigger.kill())
        }
    }, [])

    return (
        <div>
            <section className="about" id="about">
                <div className="about-container">
                    <div className="section-heading" ref={aboutHeadingRef}>
                        <div className="section-label new-label-sec">ABOUT ME</div>
                        <h2>
                            <BlurText
                                text="I DON'T JUST WRITE CODE."
                                delay={0}
                                duration={1.5}
                                animateBy="words"
                                direction="top"
                                useScrollTrigger={true}
                            />
                            <br />
                            <BlurText
                                text="I BUILD EXPERIENCES."
                                delay={0}
                                duration={1.5}
                                animateBy="words"
                                direction="top"
                                useScrollTrigger={true}
                            />
                        </h2>
                        <p>
                            I'm Adel Mohamed, a Front-End Developer focused on creating modern,
                            responsive and user‑friendly web experiences.
                        </p>
                    </div>
                    <div className="about-content">
                        <div className="about-row-top">
                            <div className="about-text">
                                <p>
                                    I enjoy turning ideas and designs into clean, interactive interfaces
                                    that look great and work smoothly across different devices.
                                </p>
                                <p>
                                    I'm continuously improving my skills in modern front‑end
                                    technologies while working on practical projects and collaborative
                                    experiences.
                                </p>
                                <a href="#projects" className="about-btn">
                                    Explore My Work <i className="fa-solid fa-arrow-right" />
                                </a>
                            </div>
                            <div className="flip-card" ref={flipCardRef}>
                                <div className="flip-card-inner">
                                    <div className="flip-card-front">
                                        <div className="flip-card-image">
                                            <img
                                                src="/assets/img/photo_2026-08-09_22-30-40.jpg"
                                                alt="Adel Mohamed"
                                            />
                                        </div>
                                        <div className="flip-card-label">
                                            <i className="fa-solid fa-arrow-right" /> HOVER ME
                                        </div>
                                    </div>
                                    <div className="flip-card-back">
                                        <div className="flip-card-back-content">
                                            <span className="flip-card-badge">20 years</span>
                                            <h3>
                                                <i className="fa-solid fa-circle-check" /> Adel Mohamed
                                            </h3>
                                            <p>Don’t wait for inspiration. Create it.</p>
                                            <div className="flip-card-social">
                                                <a
                                                    href="https://wa.me/201005056744?text=Hello%20Adel%2C%20I%20visited%20your%20portfolio."
                                                    target="_blank"
                                                    rel="noopener noreferrer"
                                                >
                                                    <i className="fa-brands fa-whatsapp fa-whatsapp-flip" />
                                                </a>
                                                <a
                                                    href="https://www.linkedin.com/in/adel-mohamed-softwareengineer/"
                                                    target="_blank"
                                                    rel="noopener noreferrer"
                                                >
                                                    <i className="fa-brands fa-linkedin-in fa-linkdin-flip" />
                                                </a>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                        <div className="about-cards" ref={aboutCardsRef}>
                            <div className="about-card education-card" data-about-card>
                                <div className="about-card-icon">
                                    <i className="fa-solid fa-graduation-cap" />
                                </div>
                                <div>
                                    <span>EDUCATION</span>
                                    <h3>Computer &amp; Information Science</h3>
                                    <p>Mansoura University</p>
                                </div>
                            </div>
                            <div className="about-card focus-card" data-about-card>
                                <div className="about-card-icon">
                                    <i className="fa-solid fa-code" />
                                </div>
                                <div>
                                    <span>FOCUS</span>
                                    <h3>Front-End Development</h3>
                                    <p>Modern &amp; Responsive Interfaces</p>
                                </div>
                            </div>
                            <div className="about-card work-card" data-about-card>
                                <div className="about-card-icon">
                                    <i className="fa-solid fa-people-group" />
                                </div>
                                <div>
                                    <span>WORK STYLE</span>
                                    <h3>Team Player</h3>
                                    <p>Collaborative &amp; Deadline-Focused</p>
                                </div>
                            </div>
                        </div>
                    </div>
                    {/*-===================== CORE STACK ============================*/}
                    <section className="stack-section">
                        <div className="stack-title">
                            <span />
                            MY CORE STACK
                            <span />
                        </div>
                        <div className="stack-track">
                            {/* SET 1 */}
                            <div className="stack-list">
                                <div className="stack-item html">
                                    <i className="fa-brands fa-html5" />
                                    <span>HTML</span>
                                </div>
                                <div className="stack-item css">
                                    <i className="fa-brands fa-css3-alt" />
                                    <span>CSS</span>
                                </div>
                                <div className="stack-item js">
                                    <i className="fa-brands fa-js" />
                                    <span>JavaScript</span>
                                </div>
                                <div className="stack-item bootstrap">
                                    <i className="fa-brands fa-bootstrap" />
                                    <span>Bootstrap</span>
                                </div>
                                <div className="stack-item tailwind">
                                    <i className="devicon-tailwindcss-original" />
                                    <span>Tailwind CSS</span>
                                </div>
                                <div className="stack-item react">
                                    <i className="fa-brands fa-react" />
                                    <span>React</span>
                                </div>
                            </div>
                            {/* SET 2 */}
                            <div className="stack-list" aria-hidden="true">
                                <div className="stack-item html">
                                    <i className="fa-brands fa-html5" />
                                    <span>HTML</span>
                                </div>
                                <div className="stack-item css">
                                    <i className="fa-brands fa-css3-alt" />
                                    <span>CSS</span>
                                </div>
                                <div className="stack-item js">
                                    <i className="fa-brands fa-js" />
                                    <span>JavaScript</span>
                                </div>
                                <div className="stack-item bootstrap">
                                    <i className="fa-brands fa-bootstrap" />
                                    <span>Bootstrap</span>
                                </div>
                                <div className="stack-item tailwind">
                                    <i className="devicon-tailwindcss-original" />
                                    <span>Tailwind CSS</span>
                                </div>
                                <div className="stack-item react">
                                    <i className="fa-brands fa-react" />
                                    <span>React</span>
                                </div>
                            </div>
                            {/* SET 3 */}
                            <div className="stack-list" aria-hidden="true">
                                <div className="stack-item html">
                                    <i className="fa-brands fa-html5" />
                                    <span>HTML</span>
                                </div>
                                <div className="stack-item css">
                                    <i className="fa-brands fa-css3-alt" />
                                    <span>CSS</span>
                                </div>
                                <div className="stack-item js">
                                    <i className="fa-brands fa-js" />
                                    <span>JavaScript</span>
                                </div>
                                <div className="stack-item bootstrap">
                                    <i className="fa-brands fa-bootstrap" />
                                    <span>Bootstrap</span>
                                </div>
                                <div className="stack-item tailwind">
                                    <i className="devicon-tailwindcss-original" />
                                    <span>Tailwind CSS</span>
                                </div>
                                <div className="stack-item react">
                                    <i className="fa-brands fa-react" />
                                    <span>React</span>
                                </div>
                            </div>
                            {/* SET 4 */}
                            <div className="stack-list" aria-hidden="true">
                                <div className="stack-item html">
                                    <i className="fa-brands fa-html5" />
                                    <span>HTML</span>
                                </div>
                                <div className="stack-item css">
                                    <i className="fa-brands fa-css3-alt" />
                                    <span>CSS</span>
                                </div>
                                <div className="stack-item js">
                                    <i className="fa-brands fa-js" />
                                    <span>JavaScript</span>
                                </div>
                                <div className="stack-item bootstrap">
                                    <i className="fa-brands fa-bootstrap" />
                                    <span>Bootstrap</span>
                                </div>
                                <div className="stack-item react">
                                    <i className="fa-brands fa-react" />
                                    <span>React</span>
                                </div>
                            </div>
                        </div>
                    </section>
                </div>
            </section>

        </div>
    )
}

export default About