import React from 'react'

function Valuesection() {
    return (
        <div>
            <section className="value-section" id="value">
                <div className="value-container">
                    <div className="value-heading">
                        <div className="section-label">WHAT I BRING</div>
                        <h2>
                            I DON'T JUST BUILD WEBSITES. <span>I BUILD EXPERIENCES.</span>
                        </h2>
                        <p>
                            My approach combines clean development, responsive interfaces and
                            attention to the details that make a website feel complete.
                        </p>
                    </div>
                    <div className="value-grid">
                        <article className="value-card value-card-pink">
                            <div className="value-card-header">
                                <span className="value-number">01</span>
                                <div className="value-icon">
                                    <i className="fa-solid fa-mobile-screen-button" />
                                </div>
                            </div>
                            <div className="value-card-body">
                                <h3>
                                    Responsive
                                    <br />
                                    By Default.
                                </h3>
                                <p>
                                    Interfaces that adapt smoothly across mobile, tablet and desktop.
                                </p>
                            </div>
                            <div className="value-line" />
                            <span className="value-keyword">ADAPTIVE</span>
                        </article>
                        <article className="value-card value-card-green">
                            <div className="value-card-header">
                                <span className="value-number">02</span>
                                <div className="value-icon">
                                    <i className="fa-solid fa-code" />
                                </div>
                            </div>
                            <div className="value-card-body">
                                <h3>
                                    Clean Code.
                                    <br />
                                    Clean Experience.
                                </h3>
                                <p>
                                    Structured and maintainable code built with performance and
                                    scalability in mind.
                                </p>
                            </div>
                            <div className="value-line" />
                            <span className="value-keyword">SCALABLE</span>
                        </article>
                        <article className="value-card value-card-dark">
                            <div className="value-card-header">
                                <span className="value-number">03</span>
                                <div className="value-icon">
                                    <i className="fa-solid fa-crosshairs" />
                                </div>
                            </div>
                            <div className="value-card-body">
                                <h3>
                                    Attention
                                    <br />
                                    To Detail.
                                </h3>
                                <p>
                                    Small details matter. From spacing and typography to interactions
                                    and animations.
                                </p>
                            </div>
                            <div className="value-line" />
                            <span className="value-keyword">PRECISE</span>
                        </article>
                    </div>
                </div>
            </section>

        </div>
    )
}

export default Valuesection