import React, { useRef, useEffect } from 'react'
import gsap from 'gsap'
import { ScrollTrigger } from 'gsap/ScrollTrigger'
import BlurText from '../components/BlurText'

gsap.registerPlugin(ScrollTrigger)

function Skills() {
    const skillsHeadingRef = useRef(null)
    const skillCardsRef = useRef(null)

    useEffect(() => {
        // Scroll reveal for heading
        if (skillsHeadingRef.current) {
            gsap.fromTo(
                skillsHeadingRef.current,
                { opacity: 0, y: 50 },
                {
                    opacity: 1,
                    y: 0,
                    duration: 0.8,
                    ease: 'power3.out',
                    scrollTrigger: {
                        trigger: skillsHeadingRef.current,
                        start: 'top 80%',
                        toggleActions: 'play none none none',
                    },
                }
            )
        }

        // Staggered animation for skill cards
        if (skillCardsRef.current) {
            gsap.fromTo(
                skillCardsRef.current.querySelectorAll('[data-skill-card]'),
                { opacity: 0, y: 40, scale: 0.9 },
                {
                    opacity: 1,
                    y: 0,
                    scale: 1,
                    duration: 0.6,
                    stagger: 0.08,
                    ease: 'back.out',
                    scrollTrigger: {
                        trigger: skillCardsRef.current,
                        start: 'top 75%',
                        toggleActions: 'play none none none',
                    },
                }
            )
        }

        return () => {
            ScrollTrigger.getAll().forEach((trigger) => trigger.kill())
        }
    }, [])

    return (
        <div>
            <section className="skills" id="skills">
                <div className="skills-container">
                    <div className="section-heading skills-heading" ref={skillsHeadingRef}>
                        <div className="section-label new-label-sec">MY SKILLS</div>
                        <h2>
                            <BlurText
                                text="TOOLS I USE TO BUILD FOR THE WEB."
                                delay={0}
                                duration={1.5}
                                animateBy="words"
                                direction="top"
                                useScrollTrigger={true}
                            />
                        </h2>
                        <p className="tech-skills-headind">
                            Technologies and tools I use to transform ideas into responsive,
                            interactive and modern web experiences.
                        </p>
                    </div>
                    <div className="skills-content">
                        <div className="skills-group">
                            <div className="skills-group-title">
                                <div className="skills-group-icon">
                                    <i className="fa-solid fa-code" />
                                </div>
                                <div>
                                    <span>01</span>
                                    <h3>Front-End Development</h3>
                                </div>
                            </div>
                            <div className="skills-grid" ref={skillCardsRef}>
                                <div className="skill-card skill-html" data-skill-card>
                                    <div className="skill-icon">
                                        <i className="fa-brands fa-html5" />
                                    </div>
                                    <div className="skill-info">
                                        <h4>HTML</h4>
                                        <p>Semantic &amp; structured websites</p>
                                    </div>
                                    <i className="fa-solid fa-arrow-up-right skill-arrow" />
                                </div>
                                <div className="skill-card skill-css" data-skill-card>
                                    <div className="skill-icon">
                                        <i className="fa-brands fa-css3-alt" />
                                    </div>
                                    <div className="skill-info">
                                        <h4>CSS</h4>
                                        <p>Responsive &amp; modern interfaces</p>
                                    </div>
                                    <i className="fa-solid fa-arrow-up-right skill-arrow" />
                                </div>
                                <div className="skill-card skill-js" data-skill-card>
                                    <div className="skill-icon">
                                        <i className="fa-brands fa-js" />
                                    </div>
                                    <div className="skill-info">
                                        <h4>JavaScript</h4>
                                        <p>Interactive web experiences</p>
                                    </div>
                                    <i className="fa-solid fa-arrow-up-right skill-arrow" />
                                </div>
                                <div className="skill-card skill-bootstrap" data-skill-card>
                                    <div className="skill-icon">
                                        <i className="fa-brands fa-bootstrap" />
                                    </div>
                                    <div className="skill-info">
                                        <h4>Bootstrap</h4>
                                        <p>Fast responsive UI development</p>
                                    </div>
                                    <i className="fa-solid fa-arrow-up-right skill-arrow" />
                                </div>
                                <div className="skill-card skill-react" data-skill-card>
                                    <div className="skill-icon">
                                        <i className="fa-brands fa-react" />
                                    </div>
                                    <div className="skill-info">
                                        <h4>React</h4>
                                        <p>Component-based interfaces</p>
                                    </div>
                                    <i className="fa-solid fa-arrow-up-right skill-arrow" />
                                </div>
                            </div>
                        </div>
                        <div className="skills-group tools-group">
                            <div className="skills-group-title">
                                <div className="skills-group-icon green-icon">
                                    <i className="fa-solid fa-wand-magic-sparkles" />
                                </div>
                                <div>
                                    <span>02</span>
                                    <h3>Tools &amp; Workflow</h3>
                                </div>
                            </div>
                            <div className="tools-list">
                                <div className="tool-item">
                                    <i className="fa-brands fa-github" />
                                    <span>GitHub</span>
                                </div>
                                <div className="tool-item">
                                    <i className="fa-brands fa-git-alt" />
                                    <span>Git</span>
                                </div>
                                <div className="tool-item">
                                    <i className="devicon-vscode-plain" />
                                    <span>VS Code</span>
                                </div>
                                <div className="tool-item">
                                    <i className="fa-brands fa-figma" />
                                    <span>Figma</span>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </section>

        </div>
    )
}

export default Skills