import React, { useEffect, useRef } from 'react';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';

gsap.registerPlugin(ScrollTrigger);

function BlurText({
    text,
    delay = 0,
    duration = 1.5,
    animateBy = 'words',
    direction = 'top',
    onAnimationComplete = null,
    className = '',
    useScrollTrigger = false,
}) {
    const textRef = useRef(null);

    useEffect(() => {
        if (!textRef.current) return;

        const elements = textRef.current.querySelectorAll('span');
        if (elements.length === 0) return;

        const directionMap = {
            top: { y: 20, x: 0 },
            bottom: { y: -20, x: 0 },
            left: { y: 0, x: 20 },
            right: { y: 0, x: -20 },
        };

        const yDir = directionMap[direction].y;
        const xDir = directionMap[direction].x;

        const animationConfig = {
            opacity: 1,
            filter: 'blur(0px)',
            y: 0,
            x: 0,
            duration,
            stagger: 0.12,
            ease: 'power3.out',
            onComplete: onAnimationComplete,
        };

        if (useScrollTrigger) {
            // Scroll reveal animation
            gsap.fromTo(
                elements,
                {
                    opacity: 0,
                    filter: 'blur(10px)',
                    y: yDir,
                    x: xDir,
                },
                {
                    ...animationConfig,
                    scrollTrigger: {
                        trigger: textRef.current,
                        start: 'top 80%',
                        end: 'top 50%',
                        toggleActions: 'play none none none',
                    },
                }
            );
        } else {
            // Immediate animation on mount
            gsap.fromTo(
                elements,
                {
                    opacity: 0,
                    filter: 'blur(10px)',
                    y: yDir,
                    x: xDir,
                },
                {
                    ...animationConfig,
                    delay,
                }
            );
        }

        return () => {
            gsap.killTweensOf(elements);
            ScrollTrigger.getAll().forEach((trigger) => trigger.kill());
        };
    }, [delay, duration, direction, useScrollTrigger, onAnimationComplete]);

    // Split text into words or characters
    const getElements = () => {
        if (animateBy === 'words') {
            return text.split(' ').map((word, index) => (
                <span key={index} style={{ display: 'inline-block', marginRight: '0.25em' }}>
                    {word}
                </span>
            ));
        } else if (animateBy === 'characters') {
            return text.split('').map((char, index) => (
                <span key={index} style={{ display: 'inline-block' }}>
                    {char}
                </span>
            ));
        }
        return text;
    };

    return (
        <span ref={textRef} className={className}>
            {getElements()}
        </span>
    );
}

export default BlurText;
